import {chapters,questions,sampleNote} from './course.js';
import {escapeHTML as e,inScope,scopedChapters,getProgress,selectSourcePages,buildMessages,renderMarkdown,validateBackup} from './core.js';
const icons={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Z"/><path d="M12 5v15"/>',
 check:'<path d="m6 12 4 4 8-9"/><rect x="3" y="3" width="18" height="18" rx="4"/>',
 folder:'<path d="M3 7V5a2 2 0 0 1 2-2h4l3 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 4 2 2 1 3 4 2 2-2 3-1 2-4-2-2-1-3-4-2Z"/>',
 arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><path d="m12 12 9-9"/>',
 spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',
 lung:'<path d="M42 13v27m-2-7c-6-6-10-10-14-7-9 6-15 24-13 34 2 10 14 13 25 5V40m6-7c6-6 10-10 14-7 9 6 15 24 13 34-2 10-14 13-25 5V40M42 30 28 43m14-13 14 13"/>'};
const svg=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 ${name==='lung'?'84 84':'24 24'}" fill="none" stroke="currentColor" stroke-width="${name==='lung'?1.4:1.5}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const defaults={mode:'midterm',progress:{},attempts:[],lastChapter:5,theme:'light',settings:{baseUrl:'',model:''}};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('physio-state')||'{}')};if(!['midterm','final'].includes(state.mode))state.mode='midterm';if(!state.progress||Array.isArray(state.progress))state.progress={};if(!Array.isArray(state.attempts))state.attempts=[];}catch{state={...defaults};}
let docs=[],notes=[],apiKey='',backend={backend:false,aiConfigured:false},db,activeTab='outline',questionFilter='all',uploadBusy=false,aiBusy=false,aiError='',aiJob=null,editNoteId=null,viewSourceId=null,questionResults={},writeDrafts={},courseQuery='';
const main=document.querySelector('#main');
document.addEventListener('click',ev=>{if(editNoteId&&ev.target.closest('a[href^="#"],[data-tab],#theme-toggle')){ev.preventDefault();ev.stopImmediatePropagation();toast('请先保存讲义修改，再切换页面。');}},true);
const save=()=>{try{localStorage.setItem('physio-state',JSON.stringify(state));}catch{toast('浏览器存储空间不足，请备份学习记录。');}};
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4000);}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('physio-study',1);r.onupgradeneeded=()=>{r.result.createObjectStore('documents',{keyPath:'id'});r.result.createObjectStore('notes',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbOp(store,method,value){return new Promise((resolve,reject)=>{const tx=db.transaction(store,method==='getAll'?'readonly':'readwrite');const req=tx.objectStore(store)[method](value);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);});}
function heading(label,title,sub,action=''){return `<section class="page-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</section>`;}
const tag=(text,warm=false)=>text?`<span class="badge ${warm?'warm':''}">${e(text)}</span>`:'';
const getChapter=id=>chapters.find(c=>c.id===Number(id));
function chapterProgress(c){const completed=c.topics.filter(t=>state.progress[t.id]==='mastered').length;return {completed,total:c.topics.length,percent:Math.round(completed/c.topics.length*100)};}
function nav(){const names=[['overview','总览','grid'],['courses','课程与大纲','book'],['practice','练习与错题','check'],['library','我的资料','folder'],['settings','设置','settings']];const page=(location.hash.slice(1)||'overview').split('/')[0];document.querySelector('#navigation').innerHTML=names.map(([id,name,icon])=>`<a href="#${id}" class="nav-item ${page===id||page==='chapter'&&id==='courses'?'active':''}">${svg(icon)}${name}${id==='library'?`<span class="nav-count">${docs.length}</span>`:''}</a>`).join('');document.querySelector('#page-label').textContent=page==='chapter'?'章节学习':names.find(n=>n[0]===page)?.[1]||'总览';document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode));});document.querySelector('#mode-description').textContent=state.mode==='midterm'?'范围：第 1—5 章':'范围：第 1—11 章';document.body.classList.toggle('dark',state.theme==='dark');}
function stat(label,value,unit,foot,icon,percent){return `<div class="stat"><div class="stat-head">${label}${svg(icon)}</div><div class="stat-value">${value}<span>${unit}</span></div><div class="stat-foot">${foot}</div>${percent!==undefined?`<div class="mini-track"><span style="width:${percent}%"></span></div>`:''}</div>`;}
function row(c){const p=chapterProgress(c);return `<a class="chapter-row" href="#chapter/${c.id}"><span class="chapter-number">${String(c.id).padStart(2,'0')}</span><div class="chapter-info"><h3>${c.name}</h3><p>${c.topics.length} 个学习单元 · 教材 pp.${c.start}–${c.end}</p></div><div class="chapter-meta">${tag(c.topics.some(t=>t.tag.includes('难点'))?'含重点 / 难点':'基础框架',c.id===4||c.id===5)}<div class="mini-track"><span style="width:${p.percent}%"></span></div><span class="chapter-percentage">${p.percent}%</span><span class="chapter-arrow">↗</span></div></a>`;}
function wrongAttempts(){return state.attempts.filter(a=>a.correct===false&&inScope({id:a.chapterId},state.mode));}
function overview(){const scoped=scopedChapters(chapters,state.mode),p=getProgress(chapters,state.progress,state.mode);let next=getChapter(state.lastChapter)||chapters[0];if(!inScope(next,state.mode))next=chapters[0];const learning=scoped.flatMap(c=>c.topics).filter(t=>state.progress[t.id]==='learning').length;const wrong=wrongAttempts();return heading('A LITTLE EVERY DAY','把知识，学成自己的。','从学校大纲出发，把理解、练习和复习连在一起。',`<div class="heading-note">生理学 A · 2026 秋季<br>第 10 版教材 / 双考试方案</div>`)+`
  <section class="hero"><div class="hero-main"><span class="eyebrow">YOUR NEXT CHAPTER / 接着学</span><h2>每一条机制，都值得想明白。</h2><p>从「${next.name}」开始，把关键概念连成因果链。<br>学一节，再用几道题看看自己是否理解。</p><a class="button" href="#chapter/${next.id}">继续学习 ${svg('arrow')}</a></div><div class="hero-visual"><div class="hero-ring">${svg('lung')}</div><span class="hero-note">UNDERSTAND · CONNECT · REMEMBER</span></div></section>
  <section class="stats" aria-label="学习统计">${stat('当前考试范围',scoped.length,'章',state.mode==='midterm'?'绪论 → 呼吸':'绪论 → 内分泌','book')}${stat('已掌握单元',p.completed,`/ ${p.total}`,`按知识点记录 · ${p.percent}% 完成`,'check',p.percent)}${stat('待巩固单元',learning,'个','自己标记的理解薄弱点','target')}${stat('练习记录',state.attempts.filter(a=>inScope({id:a.chapterId},state.mode)).length,'次',`<span class="accent">${wrong.length} 条</span> 待回看的错误记录`,'clock')}</section>
  <div class="dashboard-grid"><section><div class="section-head"><h2>课程地图 <small>按大纲顺序学习</small></h2><a href="#courses">查看全部 ↗</a></div><div class="chapter-list">${scoped.slice(0,state.mode==='midterm'?5:6).map(row).join('')}</div><div class="bottom-note">${svg('spark')}<span>「掌握 / 熟悉 / 了解」与「重点 / 难点」是两个维度。<br>未标重点的内容，同样保留在学习范围内。</span></div></section>
  <aside><div class="panel"><div class="panel-label"><h3>现在做这三件事</h3><small>给学习留一点余地</small></div><div class="action-item"><span class="action-num">01</span><div><strong>读懂一个知识点</strong><p>${next.name} · 先看大纲，再看讲义</p><a href="#chapter/${next.id}">开始这一节 →</a></div></div><div class="action-item"><span class="action-num">02</span><div><strong>闭卷，检验一下理解</strong><p>呼吸试学题 · 含解析与教材依据</p><a href="#practice">做几道练习 →</a></div></div><div class="action-item"><span class="action-num">03</span><div><strong>${docs.length?'整理自己的课程资料':'放入你的教材与大纲'}</strong><p>按章选取原文，生成自己的讲义</p><a href="#library">${docs.length?'查看资料':'上传资料'} →</a></div></div></div>
  <div class="panel exam-note"><span class="eyebrow">EXAM NOTES</span><h3 style="margin-top:10px">${state.mode==='midterm'?'期中 · 到呼吸结束':'期末 · 前后内容都要学'}</h3>${state.mode==='midterm'?'<p>第 1—5 章。大纲写明机考，具体题型与时长尚未给出。</p><p>优先练清概念、机制与计算。</p>':'<p>第 1—11 章，保留期中内容。练题之外，也练完整的书面表达。</p><div class="ratio"><span></span><span></span></div><div class="ratio-labels"><span>客观题 50%</span><span>主观题 50%</span></div>'}<p>依据：课程大纲 · 考核方式</p></div></aside></div>`;}
function courses(){const scoped=scopedChapters(chapters,state.mode);return heading('COURSE MAP','一张大纲，走完一门课。',`${state.mode==='midterm'?'期中覆盖第 1—5 章':'期末覆盖第 1—11 章'} · 重点来自课程大纲，学时不等于考试分值。`)+`<div class="toolbar"><input id="course-search" class="search-input" type="search" placeholder="搜索章节或知识点，如：静息电位" value="${e(courseQuery)}" aria-label="搜索章节或知识点"><span class="badge neutral">${scoped.length} 个章节</span></div><div class="course-grid" id="course-grid">${courseCards(scoped,courseQuery)}</div><p class="coverage">这是一份按学校大纲整理的学习地图。每个条目可能合并多个原文要点；精确要求请以原大纲和老师最新通知为准。第12、13章未纳入本课程。</p>`;}
function courseCards(list,query){const filtered=list.filter(c=>[c.name,...c.topics.map(t=>t.name)].some(t=>t.toLowerCase().includes(query.toLowerCase())));return filtered.map(c=>{const p=chapterProgress(c);return `<a class="chapter-card" href="#chapter/${c.id}"><div class="card-top"><span class="chapter-number">${String(c.id).padStart(2,'0')}</span>${tag(c.id<=5?'期中 + 期末':'期末',c.id>5)}</div><h3>${c.name}</h3><p>${c.summary}</p><div class="mini-track"><span style="width:${p.percent}%"></span></div><div class="card-bottom"><span>${p.completed}/${p.total} 已掌握 · ${c.hours} 课堂学时</span><span>开始学习 ↗</span></div></a>`;}).join('')||'<div class="empty-state"><h3>没有匹配的章节</h3><p>试试更短的关键词。</p></div>';}
function noteFor(c){return notes.find(n=>n.chapterId===c.id&&n.mode===state.mode);}
function chapter(id){const c=getChapter(id);if(!c)return '<div class="empty-state"><h3>章节不存在</h3><a href="#courses">返回课程</a></div>';if(!inScope(c,state.mode))return heading('OUTSIDE THE SCOPE','本章在期末范围内。','当前期中方案仅覆盖第1—5章。')+'<button class="button" data-action="switch-final">切换到期末方案 →</button>';
state.lastChapter=c.id;save();const p=chapterProgress(c);const note=noteFor(c);return heading(`CHAPTER ${String(c.id).padStart(2,'0')}`,c.name,c.summary,`<a href="#courses" class="button secondary small">← 课程地图</a>`)+`<div class="course-tabs" role="tablist">${[['outline','大纲与进度'],['lesson','学习讲义'],['sources','原文依据']].map(([id,label])=>`<button role="tab" aria-selected="${activeTab===id}" data-tab="${id}" class="${activeTab===id?'active':''}">${label}</button>`).join('')}</div><div class="detail-layout"><section>${activeTab==='outline'?`<div class="goal-note">先理解「${c.name}」的基本过程，再解释变化的原因。标签保留大纲要求；合并条目中出现多种要求时，学习时分别对照。</div><div class="panel">${c.topics.map(t=>`<div class="topic-row"><div><div class="topic-title">${e(t.name)}</div><div class="topic-tags">${tag(t.level)}${tag(t.tag,t.tag.includes('难点'))}</div></div><select aria-label="${e(t.name)}的学习状态" data-progress="${t.id}">${[['new','未开始'],['learning','待巩固'],['mastered','已掌握']].map(([v,label])=>`<option value="${v}" ${state.progress[t.id]===v?'selected':''}>${label}</option>`).join('')}</select></div>`).join('')}</div>`:activeTab==='lesson'?lesson(c,note):sources(c)}</section>
<aside><div class="panel"><span class="eyebrow">CHAPTER PROGRESS</span><div class="stat-value">${p.percent}<span>%</span></div><div class="mini-track"><span style="width:${p.percent}%"></span></div><p class="coverage">${p.completed} / ${p.total} 单元标记为已掌握</p><a href="#practice/${c.id}" class="button soft small">练习本章 ${svg('arrow')}</a></div><div class="panel" style="margin-top:17px"><h3>本章阅读位置</h3><p class="coverage">教材正文 pp.${c.start}–${c.end}<br>已确认教材 PDF：第 ${c.start+23}–${c.end+23} 页</p><p class="source-list">纸书页码与PDF页序不同。其他版本请按文档实际内容匹配。</p></div><div class="panel" style="margin-top:17px"><h3>${state.mode==='midterm'?'期中学习方式':'期末答题方式'}</h3><p class="coverage">${state.mode==='midterm'?'闭卷说清概念 → 解释机制 → 计算或辨析 → 回看错因。':'概念 → 关键环节 → 变化方向 → 结论与条件。主观题参考评分点需自行核对。'}</p></div></aside></div>`;}
function lesson(c,note){const isSample=!note&&c.id===5;const text=note?.content||(isSample?sampleNote:'');const editing=note&&editNoteId===note.id;return `${aiError?`<div class="error-banner">${e(aiError)}</div>`:''}<div class="toolbar"><button class="button" data-action="generate" data-chapter="${c.id}" ${aiBusy?'disabled':''}>${svg('spark')}${aiBusy?'正在根据原文生成…':note?'重新生成讲义':'用我的资料生成讲义'}</button>${text?`<button class="button secondary" data-action="download-note" data-chapter="${c.id}">导出 Markdown</button><button class="button secondary" data-action="${editing?'save-note':'edit-note'}" data-chapter="${c.id}">${editing?'保存修改':'编辑讲义'}</button>`:''}</div>${text?`<p class="coverage">${isSample?'呼吸试学样稿 · 两个单元已核对教材 · 其余内容待补齐':`我的${state.mode==='midterm'?'期中':'期末'}讲义 · ${note.origin==='manual'?'人工编辑':'AI生成，需核对'} · ${new Date(note.updatedAt).toLocaleDateString('zh-CN')}`}</p><div class="panel">${editing?`<label for="note-editor" class="eyebrow">修改后保存到此浏览器</label><textarea id="note-editor" class="note-editor">${e(text)}</textarea>`:`<article class="prose">${renderMarkdown(text)}</article>`}</div>${note?.sources?.length?`<div class="panel" style="margin-top:20px"><h3>本次生成使用的原文</h3><p class="coverage">选取${note.sources.length}页/分段，覆盖可能不完整。展开回查内容。</p>${note.sources.map(s=>`<details class="source-card"><summary>${e(s.fileName)} · ${s.kind==='segment'?'分段':'PDF页序'} ${s.page}${s.truncated?' · 已截断':''}</summary><p style="white-space:pre-wrap">${e(s.text)}</p></details>`).join('')}</div>`:''}`:`<div class="empty-state"><h3>把这一章，整理成自己的讲义。</h3><p>先上传教材和大纲，配置模型，再按章节生成。原文不足时会提示补充，不会预先填入一份假讲义。</p><a href="#library" class="button secondary">上传课程资料 →</a></div>`}`;}
function sources(c){const pages=selectSourcePages(docs,c);return `<div class="goal-note">只展示实际上传并匹配到的原文。确认是这本第10版教材后，才使用已核实的PDF页码偏移。</div>${pages.length?`<div class="panel"><h3>本章资料依据</h3><p class="coverage">按页码范围或关键词选取，最多约22000字；选页不等于整章完整覆盖。</p>${pages.map(s=>`<details class="source-card"><summary>${e(s.fileName)} · ${docs.find(d=>d.id===s.documentId)?.kind==='segment'?'分段':'PDF页序'} ${s.page}${s.truncated?' · 已截断':''}</summary><p style="white-space:pre-wrap">${e(s.text)}</p></details>`).join('')}</div>`:'<div class="empty-state"><h3>还没有匹配到本章资料</h3><p>上传教材或课件后，这里会显示本章原文。无需把个人教材放到公开仓库。</p><a href="#library" class="button">去上传 →</a></div>'}`;}
function library(){return heading('YOUR MATERIALS','让资料，为你所用。','教材提供依据，大纲确定范围；你的文件保存在此浏览器。')+`<div class="upload-zone ${uploadBusy?'busy':''}" id="upload-zone">${svg('upload')}<h3>${uploadBusy?'正在提取原文，请稍候…':'把教材、大纲或课件放进来'}</h3><p>${backend.backend?'支持 PDF / DOC / DOCX / TXT / Markdown · 单个文件不超过48 MB':'在线预览支持 TXT / Markdown；PDF和Word解析请运行开源项目的本地服务。'}</p><label class="button" for="upload-files">选择文件 ${svg('arrow')}</label><input id="upload-files" class="file-input" type="file" accept=".pdf,.doc,.docx,.txt,.md" multiple ${uploadBusy?'disabled':''}></div><div class="goal-note">上传后设置资料角色。只有你确认「生理学第10版原文件」时，系统才按正文页码+23匹配章节。新大纲可作为AI生成参考；当前课程地图仍使用已确认的大纲，暂不自动替换。</div>${docs.length?docs.map(d=>`<div class="file-row"><div class="file-row-top"><span class="chapter-number">${d.ext==='pdf'?'P':'T'}</span><div class="file-detail"><h3>${e(d.name)}</h3><p>${d.pages.length} ${d.kind==='segment'?'个文本分段':'个PDF页面'} · ${Math.round(d.chars/1000)}k 字符 · ${new Date(d.createdAt).toLocaleDateString('zh-CN')}</p></div><select class="file-role" data-doc-role="${d.id}" aria-label="${e(d.name)}的资料角色">${[['textbook','教材'],['syllabus','课程大纲'],['slides','课件 / 笔记']].map(([v,label])=>`<option value="${v}" ${d.role===v?'selected':''}>${label}</option>`).join('')}</select><button class="button secondary small" data-action="preview-file" data-id="${d.id}">${viewSourceId===d.id?'收起':'查看原文'}</button><button class="icon-button" aria-label="删除${e(d.name)}" data-action="delete-file" data-id="${d.id}">×</button></div>${d.ext==='pdf'&&d.role==='textbook'?`<label class="coverage" style="display:flex;gap:8px;align-items:center"><input type="checkbox" data-doc-edition="${d.id}" ${d.edition==='physiology-10'?'checked':''}>这是已核实的《生理学》第10版 PDF（正文p.1位于PDF第24页）</label>`:''}${d.warning?`<p class="warning">${e(d.warning)}</p>`:''}${viewSourceId===d.id?`<div class="file-preview">${e(d.pages.slice(0,5).map(p=>`[${d.kind==='segment'?'分段':'PDF页'} ${p.page}]\n${p.text}`).join('\n\n'))}</div><p class="coverage">预览前5页/分段，完整内容在章节依据中匹配。</p>`:''}</div>`).join(''):'<div class="empty-state"><h3>这里等待你的第一份资料</h3><p>已内置大纲整理的课程地图和呼吸样稿。你可以先试学，再加入自己的资料。</p><a href="#chapter/5" class="button secondary">打开呼吸试学 →</a></div>'}`;}
function practice(chapterId){const c=chapterId?getChapter(chapterId):null;if(c&&!inScope(c,state.mode))return '<div class="empty-state"><h3>本章不在期中范围内</h3><button class="button" data-action="switch-final">切换期末</button></div>';const wrongIds=new Set(wrongAttempts().map(a=>a.questionId));const list=questions.filter(q=>inScope({id:q.chapter},state.mode)&&(!c||q.chapter===c.id)&&(state.mode==='final'||q.type==='choice')&&(questionFilter!=='wrong'||wrongIds.has(q.id)));return heading('ACTIVE RECALL',c?`${c.name} · 学完，试着说出来。`:'学完，试着说出来。',`${state.mode==='midterm'?'期中练习：概念辨析与计算':'期末练习：客观辨析 + 主观机制表达'} · 当前内置6道呼吸试学题。`)+`<div class="toolbar"><div class="filter-chips"><button data-filter="all" class="${questionFilter==='all'?'active':''}">全部练习</button><button data-filter="wrong" class="${questionFilter==='wrong'?'active':''}">错题回看</button></div><a href="#chapter/5" class="button secondary small">回到呼吸讲义 ↗</a></div><div class="goal-note">${state.mode==='final'?'期末大纲为客观与主观各50%。此处是试学题集，题数比例不代表完整模拟卷。主观题采用参考要点自查，未接入自动评分。':'学校期中为机考，具体题型尚未给出。当前使用客观题练理解；完整机考试卷需补充老师要求。'}</div><div class="quiz-layout">${list.length?list.map((q,i)=>questionCard(q,i)).join(''):`<div class="empty-state"><h3>${questionFilter==='wrong'?'本范围暂时没有错题':'本章练习还未编写'}</h3><p>${questionFilter==='wrong'?'作答后，答错的题会自动进入这里。':'当前只提供已核对的呼吸试学题，可以先学习本章大纲与讲义。'}</p></div>`}</div>`;}
function questionCard(q,i){const r=questionResults[q.id];return `<section class="question-card"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${q.type==='choice'?'概念与计算':'主观题 · 参考要点自查'}</span><h3>${e(q.prompt)}</h3>${q.type==='choice'?`<form data-quiz="${q.id}"><div class="options">${q.options.map((o,j)=>`<label class="option"><input type="radio" name="answer" value="${j}" ${r?.answer===j?'checked':''} required><span>${String.fromCharCode(65+j)}. ${e(o)}</span></label>`).join('')}</div><button class="button small" type="submit">${r?'再次作答':'提交答案'} →</button></form>${r?`<div class="feedback ${r.correct?'':'wrong'}"><strong>${r.correct?'答对了。再解释一下为什么。':`这道题需要回看 · 正确答案 ${String.fromCharCode(65+q.answer)}`}</strong>${e(q.explanation)}<p class="source">${e(q.source)}</p></div>`:''}`:`<label class="question-meta" for="answer-${q.id}">先写自己的答案，再展开参考要点。</label><textarea id="answer-${q.id}" data-written="${q.id}" placeholder="用概念 → 关键环节 → 效应 → 条件组织答案…">${e(writeDrafts[q.id]||'')}</textarea><button class="button secondary small" style="margin-top:14px" data-action="show-reference" data-id="${q.id}">展开参考与自查 →</button><div id="reference-${q.id}" ${r?.revealed?'':'hidden'} class="feedback"><strong>参考答案 · 非学校评分细则</strong><p>${e(q.reference)}</p><form data-written-check="${q.id}"><div class="criteria">${q.criteria.map((t,j)=>`<label><input type="checkbox" name="criteria" value="${j}">${e(t)}</label>`).join('')}</div><button class="button small">记录本次自查</button></form><p class="source">${e(q.source)}</p>${r?.checked!==undefined?`<p>上次自查覆盖 ${r.checked} / ${q.criteria.length} 个要点。此结果不等于考试得分。</p>`:''}</div>`}</section>`;}
function settings(){return heading('MAKE IT YOURS','适合自己的，才用得久。','连接模型、备份记录，让你的学习资料可以带走。')+`<div class="settings-panel"><section class="panel"><h3>AI 模型连接</h3><div class="goal-note">${backend.backend?'本地服务已连接。密钥可填写到服务端.env；网页中填写的密钥仅保留在本次页面会话。':'当前为静态在线预览。可使用支持浏览器跨域的模型服务直接生成；若连接被拦截，请运行本地服务。'}</div><form id="settings-form"><div class="form-grid"><div class="field full"><label for="base-url">兼容服务地址</label><input id="base-url" type="url" placeholder="https://你的模型服务/v1" value="${e(state.settings.baseUrl||backend.baseUrl||'')}"><small>填写服务的 API 根地址，程序追加 /chat/completions。使用你的模型供应商提供的地址。</small></div><div class="field"><label for="model-name">模型名称</label><input id="model-name" placeholder="供应商提供的模型 ID" value="${e(state.settings.model||backend.model||'')}"></div><div class="field"><label for="api-key">API Key</label><input id="api-key" type="password" autocomplete="off" placeholder="${backend.aiConfigured?'服务端已配置，可留空':'仅保留在本次页面会话'}" value="${e(apiKey)}"><small>生成时，选中的资料片段会发送给你配置的模型服务。</small></div></div><div class="button-row" style="margin-top:20px"><button class="button" type="submit">保存连接设置</button><button class="button secondary" type="button" data-action="clear-key">清除本次密钥</button></div></form><p class="inline-status">${backend.aiConfigured?'服务端密钥已配置；未调用模型确认可用性。':'尚未验证模型连接。保存后在章节讲义中发起真实生成。'}</p></section>
<section class="panel"><h3>数据备份与恢复</h3><p class="coverage">学习进度、作答记录、上传资料的提取文本和生成讲义保存在浏览器。备份可带到另一台设备；API Key不进入备份。恢复将替换当前资料和记录。</p><div class="button-row"><button class="button" data-action="backup">导出完整备份</button><label class="button secondary" for="import-backup">导入备份</label><input id="import-backup" class="file-input" type="file" accept=".json"><button class="button secondary" data-action="reset-progress">重置学习记录</button></div></section>
<section class="panel"><h3>关于这个版本</h3><p class="coverage">Physio Study v0.1 · MIT 开源代码。课程地图按已确认的生理学A大纲整理，教材和大纲原文件不包含在源码中。网站不自动预测考试成绩；记录的“掌握”来自你的标记，主观题由参考要点自查。</p><p class="coverage">已实现：双考试范围、知识点进度、资料导入、本地PDF/Word解析、按章选页、模型生成、讲义编辑与导出、自测与错题、备份恢复。尚未实现：OCR、多用户、整课自动考点映射、完整题库和自动评分。</p></section></div>`;}
function render(){nav();const [route,id]=(location.hash.slice(1)||'overview').split('/');main.innerHTML=route==='courses'?courses():route==='chapter'?chapter(id):route==='practice'?practice(id):route==='library'?library():route==='settings'?settings():overview();if(route==='library')setupDrop();}
function setupDrop(){const zone=document.querySelector('#upload-zone');zone.addEventListener('dragover',ev=>{ev.preventDefault();zone.classList.add('dragover');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragover'));zone.addEventListener('drop',ev=>{ev.preventDefault();zone.classList.remove('dragover');uploadFiles([...ev.dataTransfer.files]);});}
function confirmAction(title,copy){return new Promise(resolve=>{const d=document.querySelector('#confirm-dialog');document.querySelector('#confirm-title').textContent=title;document.querySelector('#confirm-copy').textContent=copy;d.showModal();let settled=false;const done=value=>{if(settled)return;settled=true;d.close();d.removeEventListener('cancel',cancel);resolve(value);};const cancel=ev=>{ev.preventDefault();done(false);};document.querySelector('#confirm-ok').onclick=()=>done(true);document.querySelector('#confirm-cancel').onclick=()=>done(false);d.addEventListener('cancel',cancel);});}
function download(name,text,type='text/markdown;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function backup(){download('physio-study-backup.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),mode:state.mode,progress:state.progress,attempts:state.attempts,documents:docs,notes},null,2),'application/json');toast('已导出备份；请妥善保存包含资料文本的文件。');}
async function uploadFiles(files){if(uploadBusy)return;uploadBusy=true;render();let succeeded=0,errors=[];for(const file of files){try{const ext=file.name.split('.').at(-1).toLowerCase();if(!['pdf','doc','docx','txt','md'].includes(ext))throw new Error('不支持此文件格式');if(file.size>48*1024*1024)throw new Error('超过48 MB，请分章上传');let parsed;if(['txt','md'].includes(ext)){const text=await file.text();parsed={pages:Array.from({length:Math.ceil(text.length/12000)},(_,i)=>({page:i+1,text:text.slice(i*12000,(i+1)*12000)})),warning:''};}else{if(!backend.backend)throw new Error('PDF/Word解析需要本地服务；在线预览可先导入TXT或Markdown');const r=await fetch('./api/extract',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-File-Extension':ext},body:file});parsed=await r.json();if(!r.ok)throw new Error(parsed.error||'文档解析失败');}if(!parsed.pages.some(p=>p.text.trim()))throw new Error('未提取到文字；扫描件需要OCR，当前版本不含OCR');const d={id:crypto.randomUUID(),name:file.name,ext,kind:ext==='pdf'?'pdf':'segment',role:/大纲|syllabus/i.test(file.name)?'syllabus':'textbook',edition:'',pages:parsed.pages,warning:parsed.warning||'',chars:parsed.pages.reduce((n,p)=>n+p.text.length,0),createdAt:new Date().toISOString()};await dbOp('documents','put',d);docs.push(d);succeeded++;}catch(err){errors.push(`${file.name}：${err.message}`);}}uploadBusy=false;render();toast(errors.length?errors.join('；'):`已导入${succeeded}份资料，下一步确认资料角色。`);}
async function generate(id){if(aiBusy)return;const c=getChapter(id);if(!c||!inScope(c,state.mode))return;const pages=selectSourcePages(docs,c);if(!pages.length){toast('请先上传能匹配本章的教材或课件。');return;}if(!apiKey&&!backend.aiConfigured){toast('请先在设置中配置模型和API Key。');location.hash='settings';return;}const existing=noteFor(c);if(existing&&!await confirmAction('重新生成这份讲义？','重新生成成功后将替换本章本考试模式下的讲义。可以先导出保留当前版本。'))return;
const mode=state.mode;const syllabus=docs.filter(d=>d.role==='syllabus').map(d=>d.pages.map(p=>p.text).join('\n')).join('\n');const messages=buildMessages(c,mode,pages,syllabus);aiBusy=true;aiJob={chapterId:c.id,mode};aiError='';render();try{const baseUrl=state.settings.baseUrl||backend.baseUrl,model=state.settings.model||backend.model;if(!baseUrl||!model)throw new Error('请在设置中填写服务地址和模型名称。');let content;
if(backend.backend){const r=await fetch('./api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apiKey,baseUrl,model,messages}),signal:AbortSignal.timeout(130000)});const x=await r.json();if(!r.ok)throw new Error(x.error||'生成失败');content=x.content;}
else{const u=new URL(baseUrl);if(u.protocol!=='https:')throw new Error('在线直连需要HTTPS服务地址。');const r=await fetch(u.href.replace(/\/$/,'')+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${apiKey}`},body:JSON.stringify({model,messages,temperature:.2,max_tokens:6500}),signal:AbortSignal.timeout(120000)});if(!r.ok)throw new Error(`模型服务HTTP ${r.status}`);const x=await r.json();content=x.choices?.[0]?.message?.content;}
if(typeof content!=='string'||!content.trim())throw new Error('模型返回空内容。');const n={id:existing?.id||crypto.randomUUID(),chapterId:c.id,mode,origin:'ai',content,model,sources:pages.map(p=>({...p,kind:docs.find(d=>d.id===p.documentId)?.kind})),updatedAt:new Date().toISOString()};await dbOp('notes','put',n);notes=notes.filter(x=>x.id!==n.id).concat(n);toast('讲义已生成并保存，请核对来源与覆盖范围。');}
catch(err){aiError=err.name==='TimeoutError'?'模型响应超时，请稍后重试。':err.message==='Failed to fetch'?'连接失败：请检查服务地址、网络和跨域设置，或使用本地服务。':err.message;toast(aiError);}finally{aiBusy=false;aiJob=null;render();}}
main.addEventListener('input',ev=>{if(ev.target.id==='course-search'){courseQuery=ev.target.value;document.querySelector('#course-grid').innerHTML=courseCards(scopedChapters(chapters,state.mode),courseQuery);}if(ev.target.dataset.written)writeDrafts[ev.target.dataset.written]=ev.target.value;});
main.addEventListener('change',async ev=>{const el=ev.target;try{if(el.dataset.progress){state.progress[el.dataset.progress]=el.value;save();toast('学习状态已保存。');render();}if(el.dataset.docRole||el.dataset.docEdition){const d=docs.find(x=>x.id===(el.dataset.docRole||el.dataset.docEdition));if(el.dataset.docRole)d.role=el.value;else d.edition=el.checked?'physiology-10':'';await dbOp('documents','put',d);render();}if(el.id==='upload-files')await uploadFiles([...el.files]);if(el.id==='import-backup'&&el.files[0]){const file=el.files[0];if(file.size>60*1024*1024)throw new Error('备份超过60 MB。');const x=validateBackup(JSON.parse(await file.text()));if(!await confirmAction('恢复这份备份？','将替换当前的资料、讲义与学习记录。建议先导出当前备份。'))return;await new Promise((resolve,reject)=>{const tx=db.transaction(['documents','notes'],'readwrite');tx.objectStore('documents').clear();tx.objectStore('notes').clear();x.documents.forEach(d=>tx.objectStore('documents').put(d));x.notes.forEach(n=>tx.objectStore('notes').put(n));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});docs=x.documents;notes=x.notes;state.progress=x.progress;state.attempts=x.attempts;state.mode=x.mode==='final'?'final':'midterm';save();render();toast('备份已恢复。');}}catch(err){toast(err.message);}});
main.addEventListener('submit',ev=>{ev.preventDefault();const f=ev.target;if(f.id==='settings-form'){const base=document.querySelector('#base-url').value.trim(),model=document.querySelector('#model-name').value.trim();try{if(base){const u=new URL(base);if(u.username||u.password||u.search||u.hash||!['https:','http:'].includes(u.protocol))throw new Error('请填写不含密钥和参数的API根地址。');}state.settings={baseUrl:base.replace(/\/$/,''),model};apiKey=document.querySelector('#api-key').value.trim();save();toast('连接设置已保存，密钥仅保留在本次会话。');}catch(err){toast(err.message);}return;}if(f.dataset.quiz){const q=questions.find(q=>q.id===f.dataset.quiz),answer=Number(new FormData(f).get('answer'));if(!Number.isInteger(answer)||answer<0||answer>=q.options.length)return;const correct=answer===q.answer;questionResults[q.id]={answer,correct};state.attempts.push({id:crypto.randomUUID(),questionId:q.id,chapterId:q.chapter,type:q.type,mode:state.mode,answer,correct,at:new Date().toISOString()});state.attempts=state.attempts.slice(-1000);if(!correct)state.progress[q.topicId]='learning';save();const y=scrollY;render();scrollTo(0,y);}if(f.dataset.writtenCheck){const q=questions.find(q=>q.id===f.dataset.writtenCheck),checked=new FormData(f).getAll('criteria').length;questionResults[q.id]={revealed:true,checked};state.attempts.push({id:crypto.randomUUID(),questionId:q.id,chapterId:q.chapter,type:'written',mode:state.mode,answer:writeDrafts[q.id]||'',checked,total:q.criteria.length,correct:checked===q.criteria.length,selfChecked:true,at:new Date().toISOString()});if(checked<q.criteria.length)state.progress[q.topicId]='learning';save();toast('自查已记录；这不是自动评分。');}});
main.addEventListener('click',async ev=>{const tab=ev.target.closest('[data-tab]');if(tab){activeTab=tab.dataset.tab;editNoteId=null;render();return;}const filter=ev.target.closest('[data-filter]');if(filter){questionFilter=filter.dataset.filter;render();return;}const b=ev.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,c=getChapter(b.dataset.chapter);try{switch(b.dataset.action){
case 'switch-final':setMode('final');break;
case 'generate':await generate(c.id);break;
case 'download-note':{const n=noteFor(c);download(`生理学-${c.name}-${state.mode==='midterm'?'期中':'期末'}.md`,n?.content||sampleNote);break;}
case 'edit-note':{let n=noteFor(c);if(!n){n={id:crypto.randomUUID(),chapterId:c.id,mode:state.mode,origin:'manual',content:sampleNote,updatedAt:new Date().toISOString(),sources:[]};await dbOp('notes','put',n);notes.push(n);}editNoteId=n.id;render();break;}
case 'save-note':{const n=noteFor(c);n.content=document.querySelector('#note-editor').value;n.updatedAt=new Date().toISOString();await dbOp('notes','put',n);editNoteId=null;render();toast('讲义修改已保存。');break;}
case 'preview-file':viewSourceId=viewSourceId===id?null:id;render();break;
case 'delete-file':if(await confirmAction('删除这份资料？','删除浏览器中的提取文本；已生成讲义及其引用快照会保留。')){await dbOp('documents','delete',id);docs=docs.filter(d=>d.id!==id);render();}break;
case 'show-reference':questionResults[id]={...questionResults[id],revealed:true};document.querySelector(`#reference-${id}`).hidden=false;break;
case 'backup':await backup();break;
case 'clear-key':apiKey='';render();toast('已清除本次会话的密钥。');break;
case 'reset-progress':if(await confirmAction('重置学习记录？','将清空知识点状态和练习记录，保留上传资料与讲义。')){state.progress={};state.attempts=[];questionResults={};save();render();toast('学习记录已重置。');}break;
}}catch(err){toast(err.message);}});
function setMode(mode){if(editNoteId){toast('请先保存讲义编辑，再切换考试方案。');return;}state.mode=mode;save();const [route,id]=location.hash.slice(1).split('/');if((route==='chapter'||route==='practice')&&id&&!inScope({id:Number(id)},mode))location.hash='courses';else render();}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
document.querySelector('#theme-toggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';save();render();};document.querySelector('#backup-side').onclick=backup;
addEventListener('hashchange',()=>{activeTab='outline';editNoteId=null;aiError='';render();scrollTo(0,0);});
addEventListener('beforeunload',ev=>{if(editNoteId||aiBusy){ev.preventDefault();ev.returnValue='';}});
try{db=await openDB();[docs,notes]=await Promise.all([dbOp('documents','getAll'),dbOp('notes','getAll')]);}catch(err){main.innerHTML='<div class="error-banner">浏览器本地数据库不可用，请退出隐私模式或启用网站存储后重新打开。</div>';throw err;}
